        extra += smoothstep(0.85, 1.0, lines) * (0.4 + 0.6 * band) * holo * 1.2;
        extra += sparkles(uv, tilt, patternScale * 0.5, sparkle * 0.5) * (holo + 0.5);
    } else if (pattern > 3.5) {
        vec3 bronze = vec3(dot(holo, vec3(0.333))) * vec3(1.10, 0.92, 0.66);
