        col *= 0.6 + 1.2 * cloud;
        extra += sparkles(uv, tilt, patternScale, sparkle) * (holo + 0.8);
        extra += sparkles(uv + 0.37, tilt * 1.3, patternScale * 1.7, sparkle * 0.7) * holo;
